--[[
* OverlordsXI shared status icon loader (Ashita v4 / D3D8).
*
* - Custom effects (789, 815+) and virtual Soul resource icons (hud_*.png) are loaded from the
*   addon's cached assets/status_icons/*.png (generated by tools/build_custom_status_dats.py).
* - Vanilla effects (1..639) are loaded from the client's ROM/119/57.DAT status icon resources.
* Textures are cached for the lifetime of the addon and never evicted (max ~750 tiny textures).
--]]

local ok_ffi, ffi = pcall(require, 'ffi')
local ok_d3d, d3d8 = pcall(require, 'd3d8')

local M = {}

local fileCache  = {}  -- path    -> texture ptr number | false
local vanilla    = {}  -- id      -> texture ptr number | false
local keepAlive  = {}  -- hold COM refs so the GC never releases a texture that is still queued in ImGui

local function getDevice()
    if not (ok_ffi and ok_d3d) then return nil end
    local ok, dev = pcall(d3d8.get_device)
    if ok then return dev end
    return nil
end

local function wrap(ptr)
    keepAlive[#keepAlive + 1] = ptr
    return tonumber(ffi.cast('uint32_t', ptr))
end

local function loadFile(path)
    local cached = fileCache[path]
    if cached ~= nil then return cached or nil end

    local dev = getDevice()
    if dev == nil then return nil end

    local f = io.open(path, 'rb')
    if f == nil then
        fileCache[path] = false
        return nil
    end
    f:close()

    local ptr = ffi.new('IDirect3DTexture8*[1]')
    if ffi.C.D3DXCreateTextureFromFileA(dev, path, ptr) ~= ffi.C.S_OK then
        fileCache[path] = false
        return nil
    end
    local id = wrap(d3d8.gc_safe_release(ffi.cast('IDirect3DBaseTexture8*', ptr[0])))
    fileCache[path] = id
    return id
end

local function loadVanilla(statusId)
    local cached = vanilla[statusId]
    if cached ~= nil then return cached or nil end

    local dev = getDevice()
    if dev == nil then return nil end

    local okRes, icon = pcall(function()
        return AshitaCore:GetResourceManager():GetStatusIconByIndex(statusId)
    end)
    if not okRes or icon == nil or icon.Bitmap == nil or icon.ImageSize == nil or icon.ImageSize <= 0 then
        vanilla[statusId] = false
        return nil
    end

    local ptr = ffi.new('IDirect3DTexture8*[1]')
    local res = ffi.C.D3DXCreateTextureFromFileInMemoryEx(
        dev, icon.Bitmap, icon.ImageSize,
        0xFFFFFFFF, 0xFFFFFFFF, 1, 0,
        ffi.C.D3DFMT_A8R8G8B8, ffi.C.D3DPOOL_MANAGED,
        ffi.C.D3DX_DEFAULT, ffi.C.D3DX_DEFAULT,
        0xFF000000, nil, nil, ptr)
    if res ~= ffi.C.S_OK then
        vanilla[statusId] = false
        return nil
    end
    local id = wrap(d3d8.gc_safe_release(ffi.cast('IDirect3DTexture8*', ptr[0])))
    vanilla[statusId] = id
    return id
end

local function assetPath(name)
    return string.format('%s/assets/status_icons/%s.png', addon.path, name)
end

-- Cached custom icon (<iconId>.png). Returns an ImGui texture id or nil.
function M.custom(iconId)
    return loadFile(assetPath(tostring(iconId)))
end

-- Virtual Soul resource icon (hud_<name>.png).
function M.hud(name)
    return loadFile(assetPath('hud_' .. tostring(name)))
end

-- Resolve the best texture for an effect.
--   catalog : status_catalog.lua table (may be nil)
--   Returns textureId, entry   (entry is the catalog row for custom effects)
function M.forEffect(catalog, effectId, iconId)
    local entry = catalog and catalog.byEffectId and catalog.byEffectId[effectId] or nil
    if entry == nil and catalog and catalog.byIconId and iconId then
        local byIcon = catalog.byIconId[iconId]
        if byIcon ~= nil and byIcon.effectId == effectId then entry = byIcon end
    end
    if entry ~= nil then
        return M.custom(entry.iconId), entry
    end
    return loadVanilla(iconId and iconId > 0 and iconId < 768 and iconId or effectId), nil
end

return M
